<script setup lang="ts">import AdminLayout from '@/Layouts/AdminLayout.vue';import{Head,router}from'@inertiajs/vue3';import{reactive}from'vue';const props=defineProps<{report:any,context:any[]}>();const form=reactive({action:'dismiss',reason:'',expires_at:''});const submit=()=>router.post(route('admin.reports.resolve',props.report.id),form);</script>
<template><Head title="Review report"/><AdminLayout><h1 class="text-2xl font-bold">Review report #{{report.id}}</h1><div class="mt-6 grid gap-6 lg:grid-cols-2"><section class="rounded-xl border bg-white p-5"><h2 class="font-semibold">Report</h2><dl class="mt-4 space-y-2 text-sm"><div><span class="text-slate-500">Reporter: </span>{{report.reporter?.name}}</div><div><span class="text-slate-500">Reason: </span>{{report.reason}}</div><div><span class="text-slate-500">Details: </span>{{report.description||'—'}}</div></dl></section><form class="rounded-xl border bg-white p-5" @submit.prevent="submit"><h2 class="font-semibold">Resolution</h2><select v-model="form.action" class="mt-4 w-full rounded border p-2"><option value="dismiss">Dismiss report</option><option value="remove_message">Remove message</option><option value="warn">Warn user</option><option value="suspend">Suspend user</option><option value="ban">Ban user</option></select><textarea v-model="form.reason" class="mt-3 w-full rounded border p-2" placeholder="Reason (required for removal, suspension, or ban)"/><input v-if="form.action==='suspend'" v-model="form.expires_at" class="mt-3 w-full rounded border p-2" type="datetime-local"><button class="mt-4 rounded bg-rose-600 px-4 py-2 text-white">Apply action</button></form></div><section class="mt-6 max-w-3xl rounded-xl border bg-white"><h2 class="border-b p-5 font-semibold">Limited moderation context</h2><div v-for="message in context" :key="message.id" class="border-b p-4 text-sm" :class="message.id===report.message_id?'bg-amber-50':''"><b>{{message.sender?.name}}</b><span v-if="message.id===report.message_id" class="ml-2 text-amber-700">Reported</span><p class="mt-1">{{message.deleted_at?'This message was removed.':(message.message || `[${message.type}]`)}}</p></div></section></AdminLayout></template>
